  box-shadow: var(--card-shadow);
  border: 1px solid var(--border-color);
  transition: background 0.18s;
}

.gallery-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
  gap: 2.1rem 1.2rem;
}

